  ('bfa5b7b7-f85a-4aa7-b862-d83cdc04410d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तरुणों के लिए जैसे भविष््यय उज््ज््व्वल होता है, वैसे हीी वृद्धधोंों के लिए अतीीत। वर््तमानन से दोनोों को असंतोष होता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7104499d-f77d-4ad8-a67c-3bed51fc5732', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तरुण भविष््यय को वर््तमानन में लानना चाहते हैं और वृद्ध अतीीत को खींचकर वर््तमानन में देखनना चाहते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dacd1563-8b0c-4ae6-899b-0115e16ba037', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तरुण क््राांति के समर््थक होते हैं और वृद्ध अतीीत-गौरव के संरक्षक। इन््हीं दोनोों के कारण वर््तमानन सदैव क्ुब्ध रहता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('51a8fa01-1b6b-4af9-b108-5f0ef9bd0b80', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भारत के इतिहास में बुद्धदेव, महावीीर स्वामीी, नन ागार्जुनन, शशंकराचार््य, कबीीर, ननाननक, राजा राममोहनन रायय, स्वामीी दययाननंद और महात्मा गांधीी में हीी सुधारकों की गणनना समाप्त नहीीं होतीी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f9bd976c-e54a-47e8-9d44-414f192a153b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ययह सच है कि जीीवनन में नन ए-ननए दोष उत्पन््न होते जाते हैं और ननए-ननए सुधार हो जाते हैं। नन दोषों का अंत है और नन सुधारों का।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1779c6c5-2bcd-4a3c-9a23-32ffa64b28cb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे आज लिखना ही पड़ेगा। अंग्रेजी के प्रसिद्ध निबंध लेखक ए.जी. गार्डिनर का कथन है कि लिखने की एक विशेष मानसिक स्थिति होती है। उस समय मन में कुछ ऐसी उमंग-सी उठती है, हृदय में कुछ ऐसी स्फूर्ति-सी आती है, मस्तिष्क में कुछ ऐसा आवेग-सा उत्पन्न होता है कि लेख लिखना ही पड़ता है। उस समय विषय की चिंता नहीं रहती। कोई भी विषय हो, उसमें हम अपने हृदय के आवेग को भर ही देते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e30d412e-84d2-4969-bb82-cff2828ca808', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हैट टाँगने के लिए कोई भी खूँटी काम दे सकती है। उसी तरह अपने मनोभावों को व्यक्त करने के लिए कोई भी विषय उपयुक्त है। असली वस्तु है हैट, खूँटी नहीं। इसी तरह मन के भाव ही तो यथार्थ वस्तु हैं, विषय नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e51526d5-2f1a-4059-8ebb-86cb737af5be', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गार्डिनर साहब के इस कथन की यथार्थता में मुझे संदेह नहीं, पर मेरे लिए कठिनता यह है कि मैंने उस मानसिक स्थिति का अनुभव ही नहीं किया है, जिसमें भाव अपने आप उत्थित हो जाते हैं। मुझे तो सोचना पड़ता है, चिंता करनी पड़ती है, परिश्रम करना पड़ता है, तब कहीं मैं एक निबंध लिख सकता हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0aaf827c-a633-4d59-a4f0-9f5ec7c0a5ff', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज तो मुझे विशेष परिश्रम करना पड़ेगा, क्योंकि मुझे कोई साधारण निबंध नहीं लिखना है। आज मुझे नमिता और अमिता के लिए आदर्श निबंध लिखना होगा। नमिता का आदेश है कि मैं ‘दूर के ढोल सुहावने होते हैं’ इस विषय पर लिखूँ। अमिता का आग्रह है कि मैं समाज-सुधार पर लिखूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ba7ec905-7f1c-4326-979d-acd2216969e4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ये दोनों ही विषय परीक्षा में आ चुके हैं और उन दोनों पर आदर्श निबंध लिखकर मुझे उन दोनों को निबंध-रचना का रहस्य समझाना पड़ेगा। दूर के ढोल सुहावने अवश्य होते हैं। पर क्या वे इतने सुहावने होते हैं कि उन पर पाँच पेज लिखे जा सकें?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1c6098d4-5b1b-4616-8850-cb577049070b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसी प्रकार जिस समाज-सुधार की चर्चा अनादि काल से लेकर आज तक होती आ रही है और जिसके संबंध में बड़े-बड़े विज्ञों में भी विरोध है, उसको मैं पाँच पेज में कैसे लिख दूँ? मैंने सोचा कि सबसे पहले निबंधशास्त्र के आचार्ययों की सम्मति जान लूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d722d1a6-0763-4664-a032-95542a162583', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले यह तो समझ लूँ कि आदर्श निबंध है क्या और वह कैसे लिखा जाता है, तब फिर मैं विषय की चिंता करूँगा। इसलिए मैंने निबंधशास्त्र के कई आचार्ययों की रचनाएँ देखीं। एक विद्वान का कथन है कि निबंध छोटा होना चाहिए। छोटा निबंध बड़े की अपेक्षा अधिक अच्छा होता है, क्योंकि बड़े निबंध में रचना की सुंदरता नहीं बनी रह सकती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('31bd795b-2474-4eba-87ec-0f750e290cd4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस कथन को मान लेने में ही मेरा लाभ है। मुझे छोटा ही निबंध लिखना है, बड़ा नहीं। पर लिखूँ कैसे? निबंधशास्त्र के उन्हीं आचार्य महोदय का कथन है कि निबंध के दो प्रधान अंग हैं— क्या लिखूँ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('716e59bc-f351-4762-95cb-a8ae6283fd8a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे आज लिखना ही पड़ेगा। अंग्रेजी के प्रसिद्ध निबंध लेखक ए.जी. गार्डिनर का कथन है कि लिखने की एक विशेष मानसिक स्थिति होती है। उस समय मन में कुछ ऐसी उमंग-सी उठती है, हृदय में कुछ ऐसी स्फूर्ति-सी आती है, मस्तिष्क में कुछ ऐसा आवेग-सा उत्पन्न होता है कि लेख लिखना ही पड़ता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c095fb25-02de-4b5b-9826-cfa70f9b9f83', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस समय विषय की चिंता नहीं रहती। कोई भी विषय हो, उसमें हम अपने हृदय के आवेग को भर ही देते हैं। हैट टाँगने के लिए कोई भी खूँटी काम दे सकती है। उसी तरह अपने मनोभावों को व्यक्त करने के लिए कोई भी विषय उपयुक्त है। असली वस्तु है हैट, खूँटी नहीं। इसी तरह मन के भाव ही तो यथार्थ वस्तु हैं, विषय नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d4e72e6c-38ba-4e9a-b9f9-eedc480e93f4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गार्डिनर साहब के इस कथन की यथार्थता में मुझे संदेह नहीं, पर मेरे लिए कठिनता यह है कि मैंने उस मानसिक स्थिति का अनुभव ही नहीं किया है, जिसमें भाव अपने आप उत्थित हो जाते हैं। मुझे तो सोचना पड़ता है, चिंता करनी पड़ती है, परिश्रम करना पड़ता है, तब कहीं मैं एक निबंध लिख सकता हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9573d048-55c3-4fdb-b6ac-e3c91264867a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज तो मुझे विशेष परिश्रम करना पड़ेगा, क्योंकि मुझे कोई साधारण निबंध नहीं लिखना है। आज मुझे नमिता और अमिता के लिए आदर्श निबंध लिखना होगा। नमिता का आदेश है कि मैं ‘दूर के ढोल सुहावने होते हैं’ इस विषय पर लिखूँ। अमिता का आग्रह है कि मैं समाज-सुधार पर लिखूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ad1bd3a8-3cb2-49d6-918c-13eef4a7f552', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ये दोनों ही विषय परीक्षा में आ चुके हैं और उन दोनों पर आदर्श निबंध लिखकर मुझे उन दोनों को निबंध-रचना का रहस्य समझाना पड़ेगा। दूर के ढोल सुहावने अवश्य होते हैं। पर क्या वे इतने सुहावने होते हैं कि उन पर पाँच पेज लिखे जा सकें?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('17ff9c8e-7724-469b-b5a9-e7730d93e577', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसी प्रकार जिस समाज-सुधार की चर्चा अनादि काल से लेकर आज तक होती आ रही है और जिसके संबंध में बड़े-बड़े विज्ञों में भी विरोध है, उसको मैं पाँच पेज में कैसे लिख दूँ? मैंने सोचा कि सबसे पहले निबंधशास्त्र के आचार्ययों की सम्मति जान लूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5bab2515-d5e6-4eda-bf16-75b9603e67a5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले यह तो समझ लूँ कि आदर्श निबंध है क्या और वह कैसे लिखा जाता है, तब फिर मैं विषय की चिंता करूँगा। इसलिए मैंने निबंधशास्त्र के कई आचार्ययों की रचनाएँ देखीं। एक विद्वान का कथन है कि निबंध छोटा होना चाहिए। छोटा निबंध बड़े की अपेक्षा अधिक अच्छा होता है, क्योंकि बड़े निबंध में रचना की सुंदरता नहीं बनी रह सकती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('84010bfb-7028-498c-9a99-f2a915f8d2c9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस कथन को मान लेने में ही मेरा लाभ है। मुझे छोटा ही निबंध लिखना है, बड़ा नहीं। पर लिखूँ कैसे? निबंधशास्त्र के उन्हीं आचार्य महोदय का कथन है कि निबंध के दो प्रधान अंग हैं— क्या लिखूँ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9b715610-558c-4f17-8919-8642ee6ddd99', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे आज लिखना ही पड़ेगा। अंग्रेजी के प्रसिद्ध निबंध लेखक ए.जी. गार्डिनर का कथन है कि लिखने की एक विशेष मानसिक स्थिति होती है। उस समय मन में कुछ ऐसी उमंग-सी उठती है, हृदय में कुछ ऐसी स्फूर्ति-सी आती है, मस्तिष्क में कुछ ऐसा आवेग-सा उत्पन्न होता है कि लेख लिखना ही पड़ता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5fd34fcc-de30-42bd-8b6a-5ed0a8730e87', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गार्डिनर साहब के इस कथन की यथार्थता में मुझे संदेह नहीं, पर मेरे लिए कठिनता यह है कि मैंने उस मानसिक स्थिति का अनुभव ही नहीं किया है, जिसमें भाव अपने आप उत्थित हो जाते हैं। मुझे तो सोचना पड़ता है, चिंता करनी पड़ती है, परिश्रम करना पड़ता है, तब कहीं मैं एक निबंध लिख सकता हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('63561d8e-95d7-4621-8d03-7216b0f0c52d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज तो मुझे विशेष परिश्रम करना पड़ेगा, क्योंकि मुझे कोई साधारण निबंध नहीं लिखना है। आज मुझे नमिता और अमिता के लिए आदर्श निबंध लिखना होगा। नमिता का आदेश है कि मैं ‘दूर के ढोल सुहावने होते हैं’ इस विषय पर लिखूँ। अमिता का आग्रह है कि मैं समाज-सुधार पर लिखूँ, ये दोनों ही विषय परीक्षा में आ चुके हैं और उन दोनों पर आदर्श निबंध लिखकर मुझे उन दोनों को निबंध-रचना का रहस्य समझाना पड़ेगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('3428cdd9-795d-4a3b-b887-e616a1b3d62d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूर के ढोल सुहावने अवश्य होते हैं। पर क्या वे इतने सुहावने होते हैं कि उन पर पाँच पेज लिखे जा सकें? इसी प्रकार जिस समाज-सुधार की चर्चा अनादि काल से लेकर आज तक होती आ रही है और जिसके संबंध में बड़े-बड़े विज्ञों में भी विरोध है, उसको मैं पाँच पेज में कैसे लिख दूँ? मैंने सोचा कि सबसे पहले निबंधशास्त्र के आचार्ययों की सम्मति जान लूँ। पहले यह तो समझ लूँ कि आदर्श निबंध है क्या और वह कैसे लिखा जाता है, तब फिर मैं विषय की चिंता करूँगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('3fcd3037-4143-4512-a564-77239e7143c0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले तो मुझे सामग्रीी एकत्र करनीी होगीी, विचार-समूह संचित करनना होगा। इसके लिए मुझे मननन करनना चाहिए। ययह तो सच है कि जिसनने जिस विषयय का अच्छा अध््ययनन कियया है, उसके मस््ततिष्क में उस विषयय के विचार आते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('58d8818e-58c7-4721-8ca8-95353299311a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर ययह कौनन जाननता था कि ‘दूर के ढोल सुहावनने’ पर भीी निबंध लिखनने की आवश््ययकता होगीी। यदि ययह बात पहले से ज्ञात होतीी तो पुस्तकालयय में जाकर इस विषयय का अननुसंधानन कर लेता; पर अब समयय नहीीं है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('302cd99a-afae-4581-8188-bd3257b5139a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे तो यहीीं बैठकर दो हीी घंटों में दो निबंध तैययार कर देनने होंगे। ययहाँ नन तो विश्वकोशश है और नन कोई ऐसा ग्रंथ जिसमें इनन विषयोों की सामग्रीी उपलब्ध हो सके। अब तो मुझे अपनने हीी ज्ञानन पर विश्वास कर लिखनना होगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e307e0f9-cecb-4a45-8567-2488709f3ea8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विज्ञों का कथनन है कि निबंध लिखनने के पहले उसकी रूपरेखा बनना लेनीी चाहिए। अतएव सबसे पहले मुझे ‘दूर के ढोल सुहावनने’ की रूपरेखा बननानीी है। मैं सोच हीी नहीीं सकता कि इस विषयय की कैसीी रूपरेखा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1b9236e1-bf73-468f-838e-4fdbe8047c70', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$निबंध लिख लेनने के बाद मैं उसका सारांशश कुछ हीी वाक््यों में भले हीी लिख दूँ, पर निबंध लिखनने के पहले उसका सार दस-पाँच शशब््दों में कैसे लिखा जाए? क््ययाया सचमुच हिंदीी के सब विज्ञ लेखक पहले से अपनने-अपनने निबंधों के लिए रूपरेखा तैययार कर लेते हैं?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('87eb71d4-f022-4909-90f1-57f7631aab0c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ए.जीी. गार्डडिननर को तो अपनने लेखों का शीर््षक बननानने में हीी सबसे अधिक कठिननाई होतीी है। उन््होंनने लिखा कि मैं लेख लिखता हूँ और शीर््षक देनने का भार मैं अपनने मित्र पर छोड़ देता हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4afd1b72-438e-4bec-b33c-37527a82fd83', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन््होंनने ययह भीी लिखा है कि शशेक्सपीययर को भीी ननाटक लिखनने में उतनीी कठिननाई नन हुई होगीी, जितनीी कठिननाई ननाटकों के ननामकरण में हुई होगीी। तभीी तो घबराकर ननाम नन रख सकनने के कारण उन््होंनने अपनने एक ननाटक का ननाम रखा ‘जैसा तुम चाहो’।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e4119f5a-d50a-4253-bde3-f17254a12f7c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए मुझसे तो रूपरेखा तैययार नन होगीी। अब मुझे शश
