  ('359e51fe-c455-459a-9f45-081c064b8943', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले तो मुझे सामग्रीी एकत्र करनीी होगीी, विचार-समूह संचित करनना होगा। इसके लिए मुझे मननन करनना चाहिए। ययह तो सच है कि जिसनने जिस विषयय का अच्छा अध््ययनन कियया है, उसके मस््ततिष्क में उस विषयय के विचार आते हैं। पर ययह कौनन जाननता था कि ‘दूर के ढोल सुहावनने’ पर भीी निबंध लिखनने की आवश््ययकता होगीी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a05f7f68-b92b-46d6-9fe0-c23e0d191bda', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विज्ञों का कथनन है कि निबंध लिखनने के पहले उसकी रूपरेखा बनना लेनीी चाहिए। अतएव सबसे पहले मुझे ‘दूर के ढोल सुहावनने’ की रूपरेखा बननानीी है। मैं सोच हीी नहीीं सकता कि इस विषयय की कैसीी रूपरेखा है। निबंध लिख लेनने के बाद मैं उसका सारांशश कुछ हीी वाक््यों में भले हीी लिख दूँ, पर निबंध लिखनने के पहले उसका सार दस-पाँच शशब््दों में कैसे लिखा जाए?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dec2bf6b-4c7e-4876-8b6b-68e11a0502af', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रदर््शनन करनने के लिए, अपनना गौरव स््थथापित करनने के लिए ययह आवश््ययक है कि वाक््यय कम-से-कम आधे पृष्ठ में तो समाप्त हों। बाणभट्ट नने कादंबरी में ऐसे हीी वाक््यय लिखे हैं। वाक््यों में अस्पष्टता भीी चाहिए, क््योंकि ययह अस्पष्टता यया दुर्बोधता गांभीर््य ला देतीी है। इसीलिए संस्कृत के प्रसिद्ध कवि श्रीीहर््ष नने जानन-बूझकर अपनने काव््यय में ऐसीी गुत््थथिययाँ डडाल दीी हैं, जो अज्ञों से नन सुलझ सकेें और सेननापति नने भीी अपनीी कविता दुर्बोध कर दीी है। तभीी तो अलंकारों, मुहावरों और लोकोक््‍ततियों का समावेशश भीी निबंधों के लिए आवश््ययक बतायया जाता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c74d6abb-d221-4e89-8938-52f44ae8cbd8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंग्रेजीी के निबंधकारों नने एक दूसरीी हीी पद्धति को अपननायया है। उननके निबंध इनन आचार्ययों की कसौटीी पर भले हीी खरे सिद्ध नन हों, पर अंग्रेजीी साहित््यय में उननका मानन अवश््यय है। उस पद्धति के जन्मदाता माननटेनन समझे जाते हैं। उन््होंनने स््वययं जो कुछ देखा, सुनना और अननुभव कियया, उसीी को अपनने निबंधों में लिपिबद्ध कर दियया। ऐसे निबंधों की सबसे बड़़ीी विशशेषता ययह है कि वे मनन की स्वच्छंद रचननाएँ हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c08973a6-0f73-4a71-afbb-a30da6391db5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनमेें नन कवि की उदात्त कल््पनना रहतीी है, नन आख््ययायिका-लेखक की सूक्षम दृष््‍टटि और नन विज्ञों की गंभीीर तर््कपूर््ण विवेचनना। उनमेें लेखक की सच््चचीी अननुभूति रहतीी है। उनमेें उसके सच्चे भावों की सच््चचीी अभिव््यक््‍तति होतीी है, उनमेें उसका उल्लास रहता है। यये निबंध तो उस मानसिक स््थथिति में लिखे जाते हैं, जिसमें नन ज्ञानन की गरिमा रहतीी है और नन कल््पनना की महिमा, जिसमें जीीवनन का गौरव भूलकर हम अपनने में हीी लीनन हो जाते है, जिसमें हम संसार को अपनीी हीी दृष््‍टटि से देखते हैं और अपनने हीी भाव से ग्रहण करते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6a2ac06f-b8e6-457f-a9a9-09c912b81dda', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब इसीी पद्धति का अननुसरण कर मैं भीी क््यों नन निबंध लिखूँ। पर मुझे तो दो निबंध लिखनने होंगे। मुझे अमीीर खुसरो की एक कहानीी ययाद आई। एक बार प््ययायास लगनने पर वे एक कुएँ के पास पहुँचे। वहाँ चार औरतें पानीी भर रहीी थीं। पानीी माँगनने पर पहले उनमेें से एक नने खीीर पर कविता सुननने की इच्छा प्रकट की, दूसरीी नने चरखे पर, तीीसरीी नने कुत्े पर और चौथीी नने ढोल पर।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('57852f8e-9786-41e3-a8a4-289eb95a900b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अमीीर खुसरो प्रतिभावानन थे, उन््होंनने एक हीी पद्य में चारों की इच्छाओं की पूर््ततिि कर दीी। उन््होंनने कहा— खीीर पकाई जतनन से, चरखा दियया चला। आयया कुत्ा खा गयया, तू बैठीी ढोल बजा।। मुझमें खुसरो की प्रतिभा नहीीं है, पर उननकी इस पद्धति को स््ववीीकार करनने से मेरीी कठिननाई आधीी रह जातीी है। मैं भीी एक निबंध में इनन दोनोों विषयोों का समावेशश कर दूँगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7df4c7b4-9792-41b3-a321-e744bd9872f0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रदर््शनन करनने के लिए, अपनना गौरव स््थथापित करनने के लिए ययह आवश््ययक है कि वाक््यय कम-से-कम आधे पृष्ठ में तो समाप्त हों। बाणभट्ट नने कादंबरी में ऐसे हीी वाक््यय लिखे हैं। वाक््यों में अस्पष्टता भीी चाहिए, क््योंकि ययह अस्पष्टता यया दुर्बोधता गांभीर््य ला देतीी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('67ecbcc4-b299-4dc9-bf91-0e86a861dc4b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसीलिए संस्कृत के प्रसिद्ध कवि श्रीीहर््ष नने जानन-बूझकर अपनने काव््यय में ऐसीी गुत््थथिययाँ डडाल दीी हैं, जो अज्ञों से नन सुलझ सकेें और सेननापति नने भीी अपनीी कविता दुर्बोध कर दीी है। तभीी तो अलंकारों, मुहावरों और लोकोक््‍ततियों का समावेशश भीी निबंधों के लिए आवश््ययक बतायया जाता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e5b739c5-c754-414e-8a09-792de0eb5e6d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंग्रेजीी के निबंधकारों नने एक दूसरीी हीी पद्धति को अपननायया है। उननके निबंध इनन आचार्ययों की कसौटीी पर भले हीी खरे सिद्ध नन हों, पर अंग्रेजीी साहित््यय में उननका मानन अवश््यय है। उस पद्धति के जन्मदाता माननटेनन समझे जाते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5c8be296-687b-4b0c-b681-24f584b7a7e9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन््होंनने स््वययं जो कुछ देखा, सुनना और अननुभव कियया, उसीी को अपनने निबंधों में लिपिबद्ध कर दियया। ऐसे निबंधों की सबसे बड़़ीी विशशेषता ययह है कि वे मनन की स्वच्छंद रचननाएँ हैं। उनमेें नन कवि की उदात्त कल््पनना रहतीी है, नन आख््ययायिका-लेखक की सूक्षम दृष््‍टटि और नन विज्ञों की गंभीीर तर््कपूर््ण विवेचनना।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('61141d71-726d-4665-9adc-65f5694b02e2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनमेें लेखक की सच््चचीी अननुभूति रहतीी है। उनमेें उसके सच्चे भावों की सच््चचीी अभिव््यक््‍तति होतीी है, उनमेें उसका उल्लास रहता है। यये निबंध तो उस मानसिक स््थथिति में लिखे जाते हैं, जिसमें नन ज्ञानन की गरिमा रहतीी है और नन कल््पनना की महिमा, जिसमें जीीवनन का गौरव भूलकर हम अपनने में हीी लीनन हो जाते है, जिसमें हम संसार को अपनीी हीी दृष््‍टटि से देखते हैं और अपनने हीी भाव से ग्रहण करते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c473ba51-8600-46ac-b18c-d1100deca1f9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब इसीी पद्धति का अननुसरण कर मैं भीी क््यों नन निबंध लिखूँ। पर मुझे तो दो निबंध लिखनने होंगे। मुझमें खुसरो की प्रतिभा नहीीं है, पर उननकी इस पद्धति को स््ववीीकार करनने से मेरीी कठिननाई आधीी रह जातीी है। मैं भीी एक निबंध में इनन दोनोों विषयोों का समावेशश कर दूँगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aaff8ef7-740e-443e-9c90-43cf0f977722', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे अमीीर खुसरो की एक कहानीी ययाद आई। एक बार प््ययायास लगनने पर वे एक कुएँ के पास पहुँचे। वहाँ चार औरतें पानीी भर रहीी थीं। पानीी माँगनने पर पहले उनमेें से एक नने खीीर पर कविता सुननने की इच्छा प्रकट की, दूसरीी नने चरखे पर, तीीसरीी नने कुत्े पर और चौथीी नने ढोल पर।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a34f5dfc-d78b-42dc-be20-4f2b98ceb31e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अमीीर खुसरो प्रतिभावानन थे, उन््होंनने एक हीी पद्य में चारों की इच्छाओं की पूर््ततिि कर दीी। उन््होंनने कहा— खीीर पकाई जतनन से, चरखा दियया चला। आयया कुत्ा खा गयया, तू बैठीी ढोल बजा।।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1c030b28-1de4-46d7-b333-b250799913e0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूर के ढोल सुहावनने होते हैं, क््योंकि उननकी कर््कशशता दूर तक नहीीं पहुँचतीी। जब ढोल के पास बैठे हुए लोगों के कानन के पर्दे फफटते रहते हैं, तब दूर किसीी ननदीी के तट पर संध््ययाया$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9bc13294-9bc4-46f7-9b1f-fbafb895fb80', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रदर््शनन करनने के लिए, अपनना गौरव स््थथापित करनने के लिए ययह आवश््ययक है कि वाक््यय कम-से-कम आधे पृष्ठ में तो समाप्त हों। बाणभट्ट नने कादंबरी में ऐसे हीी वाक््यय लिखे हैं। वाक््यों में अस्पष्टता भीी चाहिए, क््योंकि ययह अस्पष्टता यया दुर्बोधता गांभीर््य ला देतीी है। इसीलिए संस्कृत के प्रसिद्ध कवि श्रीीहर््ष नने जानन-बूझकर अपनने काव््यय में ऐसीी गुत््थथिययाँ डडाल दीी हैं, जो अज्ञों से नन सुलझ सकेें और सेननापति नने भीी अपनीी कविता दुर्बोध कर दीी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a477c3da-fee3-40f1-82f2-e6146564d6ce', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तभीी तो अलंकारों, मुहावरों और लोकोक््‍ततियों का समावेशश भीी निबंधों के लिए आवश््ययक बतायया जाता है। तब क््ययाया कियया जाए? अंग्रेजीी के निबंधकारों नने एक दूसरीी हीी पद्धति को अपननायया है। उननके निबंध इनन आचार्ययों की कसौटीी पर भले हीी खरे सिद्ध नन हों, पर अंग्रेजीी साहित््यय में उननका मानन अवश््यय है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('af9143b0-3435-4001-a633-096b9538f1d8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस पद्धति के जन्मदाता माननटेनन समझे जाते हैं। उन््होंनने स््वययं जो कुछ देखा, सुनना और अननुभव कियया, उसीी को अपनने निबंधों में लिपिबद्ध कर दियया। ऐसे निबंधों की सबसे बड़़ीी विशशेषता ययह है कि वे मनन की स्वच्छंद रचननाएँ हैं। उनमेें नन कवि की उदात्त कल््पनना रहतीी है, नन आख््ययायिका-लेखक की सूक्षम दृष््‍टटि और नन विज्ञों की गंभीीर तर््कपूर््ण विवेचनना।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('59101644-e00d-4871-ba9f-6ed378a571d4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनमेें लेखक की सच््चचीी अननुभूति रहतीी है। उनमेें उसके सच्चे भावों की सच््चचीी अभिव््यक््‍तति होतीी है, उनमेें उसका उल्लास रहता है। यये निबंध तो उस मानसिक स््थथिति में लिखे जाते हैं, जिसमें नन ज्ञानन की गरिमा रहतीी है और नन कल््पनना की महिमा, जिसमें जीीवनन का गौरव भूलकर हम अपनने में हीी लीनन हो जाते है, जिसमें हम संसार को अपनीी हीी दृष््‍टटि से देखते हैं और अपनने हीी भाव से ग्रहण करते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('89560499-a4ae-4d11-be28-747a8d12261b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब इसीी पद्धति का अननुसरण कर मैं भीी क््यों नन निबंध लिखूँ। पर मुझे तो दो निबंध लिखनने होंगे। मुझे अमीीर खुसरो की एक कहानीी ययाद आई। एक बार प््ययायास लगनने पर वे एक कुएँ के पास पहुँचे। वहाँ चार औरतें पानीी भर रहीी थीं। पानीी माँगनने पर पहले उनमेें से एक नने खीीर पर कविता सुननने की इच्छा प्रकट की, दूसरीी नने चरखे पर, तीीसरीी नने कुत्े पर और चौथीी नने ढोल पर।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6c11a74f-fbdb-42b3-9f21-ec01b9febc49', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अमीीर खुसरो प्रतिभावानन थे, उन््होंनने एक हीी पद्य में चारों की इच्छाओं की पूर््ततिि कर दीी। उन््होंनने कहा— खीीर पकाई जतनन से, चरखा दियया चला। आयया कुत्ा खा गयया, तू बैठीी ढोल बजा।। मुझमें खुसरो की प्रतिभा नहीीं है, पर उननकी इस पद्धति को स््ववीीकार करनने से मेरीी कठिननाई आधीी रह जातीी है। मैं भीी एक निबंध में इनन दोनोों विषयोों का समावेशश कर दूँगा। दूर के ढोल सुहावनने होते हैं, क््योंकि उननकी कर््कशशता दूर तक नहीीं पहुँचतीी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1905abaf-2a04-44a8-a008-95d3770d6270', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$समयय, किसीी दूसरे के कानन में वहीी शशब्द मधुरता का संचार कर देते हैं। ढोल के उन््हीं शशब््दों को सुननकर वह अपनने हृदयय में किसीी के विवाहोत्सव का चित्र अंकित कर लेता है। कोलाहल से पूर््ण घर के एक कोनने में बैठीी हुई किसीी लज््जजाशीशील ननव-वधू की कल््पनना वह अपनने मनन में कर लेता है। उस ननव-वधू के प्रेम, उल्लास, संकोच, आशशंका और विषाद से ययुक्त हृदयय के कंपनन ढोल की कर््कशश ध््वनि को मधुर बनना देते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2061644d-87d4-4aba-a15b-11cfe83b30a4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सच तो ययह है कि ढोल की ध्‍वनि के साथ आननंद का कलरव, उत्सव का प्रमोद और प्रेम का संगीीत, यये तीनोों मिले रहते हैं। तभीी उसकी कर््कशशता समीीपस्थ लोगों को भीी कटु नहीीं प्रतीीत होतीी और दूरस्थ लोगों के लिए तो वह अत््ययंयंत मधुर बनन जातीी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b1892b4a-fba2-459b-8282-9182b67b063d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ययह बात सच है कि दूर रहनने से हमें ययथार््थता की कठोरता का अननुभव नहीीं होता। ययहीी कारण है कि जो तरुण संसार के जीीवनन-संग्राम से दूर हैं, उन््हें संसार का चित्र बड़ा हीी मननमोहक प्रतीीत होता है; जो वृद्ध हो गए हैं, जो अपनीी बाल््ययायावस्था और तरुणावस्था से दूर हट आए हैं, उन््हें अपनने अतीीतकाल की स््मृति बड़़ीी सुखद लगतीी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('98649a5e-1d3d-4291-a452-ad91776ce7c0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वे अतीीत का हीी स्वप््न देखते हैं। तरुणों के लिए जैसे भविष््यय उज््ज््व्वल होता है, वैसे हीी वृद्धधोंों के लिए अतीीत। वर््तमानन से दोनोों को असंतोष होता है। तरुण भविष््यय को वर््तमानन में लानना चाहते हैं और वृद्ध अतीीत को खींचकर वर््तमानन में देखनना चाहते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('858eb631-66d6-4323-9e1a-0ce640ff81a0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तरुण क््राांति के समर््थक होते हैं और वृद्ध अतीीत-गौरव के संरक्षक। इन््हीं दोनोों के कारण वर््तमानन सदैव क्ुब्ध रहता है और इसीी से वर््तमानन काल सदैव सुधारों का काल बनना रहता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('83a2edf5-bd51-41b4-97fd-7aa3be008dbc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मननुष््यय जाति के इतिहास में कोई ऐसा काल हीी नहीीं हुआ, जब सुधारों की आवश््ययकता नन हुई हो। तभीी तो आज तक कितनने हीी सुधारक हो गए हैं, पर सुधारों का अंत कब हुआ है? भारत के इतिहास में बुद्धदेव, महावीीर स्वामीी, नन ागार्जुनन, शशंकराचार््य, कबीीर, ननाननक, राजा राममोहनन रायय, स्वामीी दययाननंद और महात्मा गांधीी में हीी सुधारकों की गणनना समाप्त नहीीं होतीी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('fce15092-3791-4480-af4d-9b098011f22f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुधारकों का दल ननगर-ननगर और गाँव-गाँव में होता है। ययह सच है कि जीीवनन में नन ए-ननए दोष उत्पन््न होते जाते हैं और ननए-ननए सुधार हो जाते हैं। नन दोषों का अंत है और नन सुधारों का। जो कभीी सुधार थे, वहीी आज दोष हो गए हैं और उनन सुधारों का फिर ननव सुधार कियया जाता है। तभीी तो यय ह जीीवनन प्रगतिशीशील मानना गयया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
