  ('e1514846-ed75-4c2c-984c-a517004dce79', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन दोनों पर आदर्श निबंध लिखकर मुझे उन दोनों को निबंध-रचना का रहस्य समझाना पड़ेगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('75f8ef13-7a5d-4da2-a3e0-f24054ea82b8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूर के ढोल सुहावने अवश्य होते हैं। पर क्या वे इतने सुहावने होते हैं कि उन पर पाँच पेज लिखे जा सकें?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3d2d334b-8a81-4891-a411-d640b809819a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसी प्रकार जिस समाज-सुधार की चर्चा अनादि काल से लेकर आज तक होती आ रही है और जिसके संबंध में बड़े-बड़े विज्ञों में भी विरोध है, उसको मैं पाँच पेज में कैसे लिख दूँ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0aa67264-2f2b-4465-8b5b-aa1d8f2cf4ca', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने सोचा कि सबसे पहले निबंधशास्त्र के आचार्ययों की सम्मति जान लूँ। पहले यह तो समझ लूँ कि आदर्श निबंध है क्या और वह कैसे लिखा जाता है, तब फिर मैं विषय की चिंता करूँगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c5a6c595-d833-48ce-b644-31b71ee93158', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए मैंने निबंधशास्त्र के कई आचार्ययों की रचनाएँ देखीं। एक विद्वान का कथन है कि निबंध छोटा होना चाहिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f1283375-dea4-47a6-9c63-b3edce8cecba', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$छोटा निबंध बड़े की अपेक्षा अधिक अच्छा होता है, क्योंकि बड़े निबंध में रचना की सुंदरता नहीं बनी रह सकती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('36e90019-418e-4cca-b5a2-4668cf2fdf6f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस कथन को मान लेने में ही मेरा लाभ है। मुझे छोटा ही निबंध लिखना है, बड़ा नहीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d5992ba7-415c-4700-b695-af546a4ef93e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर लिखूँ कैसे? निबंधशास्त्र के उन्हीं आचार्य महोदय का कथन है कि निबंध के दो प्रधान अंग हैं— क्या लिखूँ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('21b5bff8-b806-40a9-96fe-1cea0fb8942c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे आज लिखना ही पड़ेगा। अंग्रेजी के प्रसिद्ध निबंध लेखक ए.जी. गार्डिनर का कथन है कि लिखने की एक विशेष मानसिक स्थिति होती है। उस समय मन में कुछ ऐसी उमंग-सी उठती है, हृदय में कुछ ऐसी स्फूर्ति-सी आती है, मस्तिष्क में कुछ ऐसा आवेग-सा उत्पन्न होता है कि लेख लिखना ही पड़ता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5249e413-84c7-4825-b33d-776f852eb6ba', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गार्डिनर साहब के इस कथन की यथार्थता में मुझे संदेह नहीं, पर मेरे लिए कठिनता यह है कि मैंने उस मानसिक स्थिति का अनुभव ही नहीं किया है, जिसमें भाव अपने आप उत्थित हो जाते हैं। मुझे तो सोचना पड़ता है, चिंता करनी पड़ती है, परिश्रम करना पड़ता है, तब कहीं मैं एक निबंध लिख सकता हूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3b4888c7-b392-498f-937d-1aafc48a0660', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले तो मुझे सामग्रीी एकत्र करनीी होगीी, विचार-समूह संचित करनना होगा। इसके लिए मुझे मननन करनना चाहिए। ययह तो सच है कि जिसनने जिस विषयय का अच्छा अध््ययनन कियया है, उसके मस््ततिष्क में उस विषयय के विचार आते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9a43a95f-d99f-4694-8358-4534e2d54cb2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर ययह कौनन जाननता था कि ‘दूर के ढोल सुहावनने’ पर भीी निबंध लिखनने की आवश््ययकता होगीी। यदि ययह बात पहले से ज्ञात होतीी तो पुस्तकालयय में जाकर इस विषयय का अननुसंधानन कर लेता; पर अब समयय नहीीं है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ec7bb7ce-98a4-4588-8dec-4a9fcfc78a11', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे तो यहीीं बैठकर दो हीी घंटों में दो निबंध तैययार कर देनने होंगे। ययहाँ नन तो विश्वकोशश है और नन कोई ऐसा ग्रंथ जिसमें इनन विषयोों की सामग्रीी उपलब्ध हो सके। अब तो मुझे अपनने हीी ज्ञानन पर विश्वास कर लिखनना होगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e3b9a215-a41e-4f9c-aee7-bc303adf03ff', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विज्ञों का कथनन है कि निबंध लिखनने के पहले उसकी रूपरेखा बनना लेनीी चाहिए। अतएव सबसे पहले मुझे ‘दूर के ढोल सुहावनने’ की रूपरेखा बननानीी है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('63f5de7e-7866-410e-9540-eb705532d3be', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं सोच हीी नहीीं सकता कि इस विषयय की कैसीी रूपरेखा है। निबंध लिख लेनने के बाद मैं उसका सारांशश कुछ हीी वाक््यों में भले हीी लिख दूँ, पर निबंध लिखनने के पहले उसका सार दस-पाँच शशब््दों में कैसे लिखा जाए?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('358f2644-13a5-4248-b997-f0d4e634a590', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'e0a290a3-1793-462a-8e2a-7500b9b3962a', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क््ययाया सचमुच हिंदीी के सब विज्ञ लेखक पहले से अपनने-अपनने निबंधों के लिए रूपरेखा तैययार कर लेते हैं? ए.जीी. गार्डडिननर को तो अपनने लेखों का शीर््षक बननानने में हीी सबसे अधिक कठिननाई होतीी है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-395Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
